result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "canonjson.py", "content": """"Canonical JSON encoder for hashing.

Rules:
- Object keys sorted by Unicode code point.
- No whitespace anywhere.
- Strings escaped minimally: only '"' and '\' plus control chars (U+0000-U+001F);
  everything else emitted raw as UTF-8.
- Integers plain; floats only allowed if integral-valued (emitted as integer),
  otherwise CanonError.
- NaN / Infinity always CanonError.
- Non-string dict keys CanonError.
"""

import hashlib
import json
import math

_ESCAPES = {
    '"': '\\"',
    "\\": "\\\\",
    "\b": "\\b",
    "\f": "\\f",
    "\n": "\\n",
    "\r": "\\r",
    "\t": "\\t",
}


class CanonError(ValueError):
    """Raised when a value cannot be represented in canonical form."""


def _encode_string(s: str) -> str:
    parts = ['"']
    for ch in s:
        esc = _ESCAPES.get(ch)
        if esc is not None:
            parts.append(esc)
        elif ord(ch) < 0x20:
            parts.append("\\u%04x" % ord(ch))
        else:
            parts.append(ch)
    parts.append('"')
    return "".join(parts)


def dumps(obj) -> str:
    """Return the canonical JSON serialization of *obj*."""
    return _encode(obj)


def _encode(obj) -> str:
    if obj is True:
        return "true"
    if obj is False:
        return "false"
    if obj is None:
        return "null"

    if isinstance(obj, str):
        return _encode_string(obj)

    if isinstance(obj, int):
        return str(obj)

    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise CanonError("NaN/Infinity not allowed")
        if obj.is_integer():
            return str(int(obj))
        raise CanonError(f"non-integral float forbidden: {obj!r}")

    if isinstance(obj, (list, tuple)):
        return "[" + ",".join(_encode(v) for v in obj) + "]"

    if isinstance(obj, dict):
        items = []
        for key in sorted(obj.keys()):
            if not isinstance(key, str):
                raise CanonError(f"non-string dict key forbidden: {key!r}")
            items.append(_encode_string(key) + ":" + _encode(obj[key]))
        return "{" + ",".join(items) + "}"

    raise CanonError(f"type not allowed in canonical JSON: {type(obj).__name__}")


def digest(obj) -> str:
    """SHA-256 hex digest of the UTF-8 encoding of dumps(obj)."""
    return hashlib.sha256(dumps(obj).encode("utf-8")).hexdigest()
"})
