import random
import string

import pytest

from canonjson import CanonError, digest, dumps


# ---------- vectors ----------

def test_vector_exact():
    assert dumps({"b": 1, "a": [1, "x"]}) == '{"a":[1,"x"],"b":1}'


def test_unicode_key_ordering():
    out = dumps({"a": 1, "é": 2, "Z": 3})
    # code points: 'Z' (0x5A) < 'a' (0x61) < 'é' (0xE9)
    assert out == '{"Z":3,"a":1,"é":2}'


# ---------- stability over random structures ----------

def _random_jsonsafe(rng, depth=0):
    choices = ["int", "str", "bool", "none", "list", "dict"]
    if depth >= 4:
        choices = choices[:4]
    kind = rng.choice(choices)
    if kind == "int":
        return rng.randint(-10**9, 10**9)
    if kind == "str":
        alphabet = string.printable + "héllo世界\U0001F600"
        n = rng.randint(0, 12)
        s = "".join(rng.choice(alphabet) for _ in range(n))
        return "".join(c for c in s if c != "\x00") or "s"
    if kind == "bool":
        return rng.choice([True, False])
    if kind == "none":
        return None
    if kind == "list":
        return [_random_jsonsafe(rng, depth + 1) for _ in range(rng.randint(0, 6))]
    keys = set()
    while len(keys) < rng.randint(0, 6):
        keys.add("".join(rng.choice(string.ascii_letters + "é世") for _ in range(rng.randint(1, 6))))
    return {k: _random_jsonsafe(rng, depth + 1) for k in keys}


def test_stability_300_seeded():
    rng = random.Random(20260824)
    for _ in range(300):
        x = _random_jsonsafe(rng)
        assert dumps(json.loads(dumps(x))) == dumps(x)


# ---------- permutation invariance ----------

def test_permutation_invariance():
    d1 = {"zeta": 1, "alpha": [1, {"m": 2, "k": 3}], "mu": {"b": True, "a": None}}
    d2 = {"mu": {"a": None, "b": True}, "alpha": [{"k": 3, "m": 2}, 1], "zeta": 1}
    assert dumps(d1) == dumps(d2)
    assert digest(d1) == digest(d2)


# ---------- numbers ----------

def test_float_integral_emits_int():
    assert dumps(2.0) == "2"
    assert dumps(-7.0) == "-7"
    assert dumps([2.0, {"x": 3.0}]) == '[2,{"x":3}]'


def test_float_nonintegral_raises():
    with pytest.raises(CanonError):
        dumps(2.5)


@pytest.mark.parametrize("bad", [float("nan"), float("inf"), float("-inf")])
def test_nan_inf_raise(bad):
    with pytest.raises(CanonError):
        dumps(bad)


# ---------- keys ----------

@pytest.mark.parametrize("key", [1, 2.5, True, None])
def test_nonstring_keys_raise(key):
    with pytest.raises(CanonError):
        dumps({key: 1})


# ---------- misc canonical form ----------

def test_no_whitespace_and_digest():
    obj = {"k": [None, False, "a\"b\\c\nd"]}
    assert dumps(obj) == '{"k":[null,false,"a\\"b\\\\c\\nd"]}'
    import hashlib
    assert digest(obj) == hashlib.sha256(dumps(obj).encode("utf-8")).hexdigest()


def test_control_chars_escaped_minimally():
    assert dumps("\x01\x1f") == '"\\u0001\\u001f"'
